def solve(cart):
    subtotal = sum(item['qty'] * item['unit_cents'] for item in cart['items'])
    return subtotal - subtotal * cart['discount'] // 100

def solve(request):
    if request['actor_tenant'] != request['record_tenant'] or request['action'] not in {'read', 'update'}:
        return False
    role = request['role']
    return role == 'admin' or role == 'viewer' and request['action'] == 'read' or role == 'owner' and request['owned']

def solve(sheet):
    dates = set(sheet['dates'])
    credited = {record['date'] for record in sheet['records'] if record['date'] in dates and record['status'] in {'present', 'excused'}}
    return {'credited': len(credited), 'enrolled': len(dates), 'eligible': bool(dates) and 4 * len(credited) >= 3 * len(dates)}

def solve(request):
    stock = dict(request['stock'])
    sku = request['sku']
    if sku not in stock:
        return {'status': 404, 'stock': stock}
    updated = stock[sku] + request['delta']
    if updated < 0:
        return {'status': 409, 'stock': stock}
    stock[sku] = updated
    return {'status': 200, 'stock': stock}

